def transform(grid):
    h, w = len(grid), len(grid[0])
    fours = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    out = [row[:] for row in grid]
    for r, c in sixes:
        out[r][c] = 0
    if not fours or not sixes:
        return out

    # The 6 marker's shape specifies the reflection orientation. A T whose
    # single-cell stem is above its bar reflects 4 to the left; a stem below
    # reflects it to the right. A cross reflects vertically toward the marker.
    row_counts = {}
    for r, _ in sixes:
        row_counts[r] = row_counts.get(r, 0) + 1
    widest_row = max(row_counts, key=row_counts.get)
    single_rows = [r for r, count in row_counts.items() if count == 1]

    if single_rows and (min(single_rows) < widest_row or max(single_rows) > widest_row):
        if min(single_rows) < widest_row:
            cmin = min(c for _, c in fours)
            for r, c in fours:
                cc = 2 * cmin - 1 - c
                if 0 <= cc < w:
                    out[r][cc] = 4
        else:
            cmax = max(c for _, c in fours)
            for r, c in fours:
                cc = 2 * cmax + 1 - c
                if 0 <= cc < w:
                    out[r][cc] = 4
    else:
        marker_center_r = sum(r for r, _ in sixes) / len(sixes)
        source_center_r = sum(r for r, _ in fours) / len(fours)
        if marker_center_r > source_center_r:
            rmax = max(r for r, _ in fours)
            for r, c in fours:
                rr = 2 * rmax + 1 - r
                if 0 <= rr < h:
                    out[rr][c] = 4
        else:
            rmin = min(r for r, _ in fours)
            for r, c in fours:
                rr = 2 * rmin - 1 - r
                if 0 <= rr < h:
                    out[rr][c] = 4
    return out
